  int a[50], n, i, j, t;
  scanf("%d", &n);
  for (i = 0; i < n; i++)
    scanf("%d", &a[i]);
  for (i = 0; i < n - 1; i++)
    for (j = 0; j < n - 1 - i; j++)
      if (a[j] < a[j + 1]) {
        t = a[j];
        a[j] = a[j + 1];
